mapper.select:
select p.id, p.house_id, p.batch_id, p.breeding_cycle_id, p.rabbit_id, p.birth_date, p.total_kits, p.live_kits, p.remark, p.create_by, p.create_time, p.update_by, p.update_time
from parturition_records p
inner join batches b on b.id = p.batch_id
where p.house_id = #{houseId} and b.house_id = #{houseId} and p.batch_id = #{batchId}
order by p.id desc
limit #{limit}

select p.id, p.house_id, p.batch_id, p.breeding_cycle_id, p.rabbit_id, p.birth_date, p.total_kits, p.live_kits, p.remark, p.create_by, p.create_time, p.update_by, p.update_time
from parturition_records p
inner join rabbits r on r.id = p.rabbit_id
where p.house_id = #{houseId} and r.house_id = #{houseId} and p.rabbit_id = #{rabbitId}
order by p.id desc
limit #{limit}
